package com.example.starter.incident;

/**
 * 处置任务状态机：OPEN → IN_PROGRESS → DONE；OPEN/IN_PROGRESS → CANCELLED；
 * OPEN/IN_PROGRESS → AUTHORIZATION_EXPIRED（资源授权到期，续期后恢复原状态）。
 * DONE 与 CANCELLED 均为终态，不允许任何后续流转。
 */
public enum TaskStatus {

    /** 待处理。 */
    OPEN,

    /** 执行中（已开始，可继续执行或完成）。 */
    IN_PROGRESS,

    /** 已完成（要求全部阻塞事件已进入 CONTAINED/RESOLVED/CLOSED，且资源授权未到期）。 */
    DONE,

    /** 已取消。 */
    CANCELLED,

    /** 资源授权已到期：禁止完成或再次分配，可由不同于原分配人的授权角色续期恢复。 */
    AUTHORIZATION_EXPIRED;
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 处置任务实体，对应 incident_tasks 表。
 * (incidentId, taskKey) 唯一，同键同内容幂等，同键不同内容冲突；
 * 每事件至多 20 个任务。doneBy/doneAt 仅 DONE 有值，cancelledBy/cancelledAt 仅 CANCELLED 有值。
 * preExpiryStatus 记录授权到期前状态（OPEN/IN_PROGRESS），仅 AUTHORIZATION_EXPIRED 有值，
 * 续期成功后恢复该状态并清空。时间均为 UTC。
 */
public record IncidentTask(
        long id,
        long incidentId,
        String taskKey,
        String groupCode,
        String title,
        TaskStatus status,
        String createdBy,
        String doneBy,
        Instant doneAt,
        String cancelledBy,
        Instant cancelledAt,
        TaskStatus preExpiryStatus,
        Instant createdAt,
        Instant updatedAt) {

    /**
     * 判断两条任务的业务内容是否一致（用于 taskKey 幂等比对；阻塞事件集合另行比对）。
     */
    public boolean sameContent(String groupCode, String title) {
        return this.groupCode.equals(groupCode) && this.title.equals(title);
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 任务资源租约实体，对应 task_resource_assignments 表（每任务至多一条当前租约）。
 * 租约区间为 [assignedAt, expiresAt)，左闭右开，UTC 口径；当前时刻 ≥ expiresAt 即到期。
 * assignedBy 为原分配人，续期必须由其以外的授权角色提交严格更大的授权版本；
 * 历史版本与操作轨迹固化在 resource_authorization_events，本表仅保存当前状态。
 */
public record TaskResourceAssignment(
        long id,
        long taskId,
        long incidentId,
        String resourceKey,
        long authorizationVersion,
        String assignedBy,
        Instant assignedAt,
        Instant expiresAt,
        Instant createdAt,
        Instant updatedAt) {

    /**
     * 判断在指定 UTC 时刻租约是否已到期（区间右开：now ≥ expiresAt 即到期）。
     */
    public boolean expiredAt(Instant now) {
        return !now.isBefore(expiresAt);
    }
}

package com.example.starter.incident;

/**
 * 资源授权证据类型，对应 resource_authorization_events.event_type。
 * 证据只增不改，按 id 排序，字段、时间精度与 null 含义保持稳定。
 */
public enum ResourceEventType {

    /** 资源分配（oldAuthorizationVersion 为空，newAuthorizationVersion 为初始版本）。 */
    ASSIGN,

    /** 到期检测（按注入时钟在命令时判定，oldAuthorizationVersion 为到期时版本，new 为空）。 */
    EXPIRY_DETECTED,

    /** 续期（old/newAuthorizationVersion 分别为续期前后版本）。 */
    RENEW,

    /** 执行拦截（授权已到期时拒绝开始/继续/完成，attemptedAction 记录被拦截动作）。 */
    EXECUTION_BLOCKED;
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 任务执行日志实体，对应 task_execution_logs 表。
 * 只增不改：授权到期后已执行日志保留；按 id 升序即发生顺序。
 * action 取值 START/CONTINUE/COMPLETE；note 仅 CONTINUE 必填，其余可为 null。
 * occurredAt 为 UTC，微秒精度。
 */
public record TaskExecutionLog(
        long id,
        long taskId,
        long incidentId,
        String action,
        String note,
        String actor,
        Instant occurredAt) {

    /** 执行动作：开始。 */
    public static final String ACTION_START = "START";

    /** 执行动作：继续执行。 */
    public static final String ACTION_CONTINUE = "CONTINUE";

    /** 执行动作：完成。 */
    public static final String ACTION_COMPLETE = "COMPLETE";
}

