    @Transactional
    public RenewalView renew(String incidentKey, String actor, TaskRenewalRequest req) {
        String commandKey = requireText(req.commandKey(), "commandKey");
        requireText(actor, "actor"); // actor from header — controller passes; blank check
        if (req.entries() == null || req.entries().isEmpty()) throw badRequest("entries 不能为空");
        // normalize entries
        record ParsedEntry(String taskKey, long newVersion, Instant newExpiresAt) {}
        List<ParsedEntry> entries = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        for (RenewalEntry e : req.entries()) {
            String taskKey = requireText(e.taskKey(), "entries[].taskKey");
            if (!seen.add(taskKey)) throw badRequest("entries 存在重复 taskKey: " + taskKey);
            if (e.newAuthorizationVersion() == null) throw badRequest("newAuthorizationVersion 不能为空");
            if (e.newExpiresAt() == null) throw badRequest("newExpiresAt 不能为空");
            entries.add(new ParsedEntry(taskKey, e.newAuthorizationVersion(), e.newExpiresAt().truncatedTo(MICROS)));
        }
        Incident incident = lockIncident(incidentKey);
        String requestHash = Idempotency.hash(incidentKey, actor, entries.stream().map(...).collect(joining(";")));
        return idempotency.run(commandKey, "resource_renew", requestHash, RenewalView.class, () -> {
            Instant now = now();
            // 1. load tasks + assignments
            Map<String, IncidentTask> entryTasks = new LinkedHashMap<>();
            Map<String, TaskResourceAssignment> entryAssignments = new LinkedHashMap<>();
            for (ParsedEntry e : entries) {
                IncidentTask task = tasks.findByKey(incident.id(), e.taskKey())
                        .orElseThrow(() -> ApiException.notFound("任务不存在: " + e.taskKey()));
                entryTasks.put(e.taskKey(), task);
                TaskResourceAssignment assignment = resources.findByTaskId(task.id())
                        .orElseThrow(() -> ApiException.unprocessable("任务未分配资源，不能续期: " + e.taskKey(), null));
                entryAssignments.put(e.taskKey(), assignment);
            }
            // 2. per-entry validation (422)
            List<IncidentTransfer> transfers = incidents.listTransfers(incident.id());
            for (ParsedEntry e : entries) {
                IncidentTask task = entryTasks.get(e.taskKey());
                TaskResourceAssignment a = entryAssignments.get(e.taskKey());
                if (task.status() == DONE || task.status() == CANCELLED)
                    throw unprocessable("任务已处于终态，不可续期: " + e.taskKey(), details);
                boolean transferredOut = transfers.stream().anyMatch(t -> t.status() == ACCEPTED && t.acceptedAt() != null && !t.acceptedAt().isBefore(a.assignedAt()));
                if (transferredOut) throw unprocessable("任务已随事件交接出去，不可续期: " + e.taskKey(), details);
                if (actor.equals(a.assignedBy())) throw unprocessable("续期人必须不同于原分配人 " + a.assignedBy(), details);
                if (e.newVersion() <= a.authorizationVersion()) throw unprocessable("新授权版本必须大于当前版本", Map.of("taskKey",..., "resourceKey",..., "currentVersion", a.authorizationVersion(), "requestedVersion", e.newVersion()));
                if (!e.newExpiresAt().isAfter(now)) throw unprocessable("新到期时刻必须晚于续期时刻", Map.of("taskKey",..., "newExpiresAt",..., "now", now));
            }
            // 3. dependency closure
