                new RenewalEntry("T-2", 5L, T0.plusSeconds(900)));
        assertThat(view.renewed()).hasSize(2);
        assertThat(assignmentVersion("T-1")).isEqualTo(2L);
        assertThat(assignmentVersion("T-2")).isEqualTo(5L);
