                "SELECT COUNT(*) FROM resource_authorization_events WHERE event_type = 'RENEW'",
                Integer.class);
        assertThat(renewEvents).isEqualTo(2);
    }

    @Test
    void renew_resourceOccupiedByOtherIncident_rejected() {
        commanding("INC-OA", "alice");
        commanding("INC-OB", "bob");
